int dx[] = {0, 0, -1, 1};
int dy[] = {-1, 1, 0, 0};

typedef struct {
    int x, y;
} Point;

Point queue[MAXN * MAXN * 4];
int front, back;

void bfs(int sx, int sy, int dist[MAXN][MAXN]) {
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            dist[i][j] = INF;

    front = back = 0;
    dist[sx][sy] = 0;
    queue[back++] = (Point){sx, sy};

    while (front < back) {
        Point p = queue[front++];
        int x = p.x, y = p.y;
        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
            if (grid[nx][ny] == '#') continue;
            int cost = (grid[nx][ny] == 'D') ? 1 : 0;
            if (dist[x][y] + cost < dist[nx][ny]) {
                dist[nx][ny] = dist[x][y] + cost;
                // 0-1 BFS: push front for cost 0, back for cost 1
                if (cost == 0) {
                    queue[--front] = (Point){nx, ny};
                } else {
                    queue[back++] = (Point){nx, ny};
                }
            }
        }
    }
}

