typedef long long ll;

#define INF ((ll)4e18)

typedef struct {
    int to;
    int next;
    int w;
} Edge;

typedef struct {
    ll d0, d1;
    int v;
    int used;
} Node;

static int cmpNode(const void *a, const void *b) {
    const Node *x = (const Node *)a;
    const Node *y = (const Node *)b;
    if (x->d0 != y->d0) return (x->d0 < y->d0) ? -1 : 1;
    if (x->d1 != y->d1) return (x->d1 < y->d1) ? -1 : 1;
    if (x->v != y->v) return x->v - y->v;
    return x->used - y->used;
}

/* Simple binary heap for Dijkstra */
typedef struct {
    ll dist;
    int v, used;
} HeapNode;

typedef struct {
    HeapNode *a;
    int sz, cap;
} Heap;

static void heap_init(Heap *h, int cap) {
    h->a = (HeapNode *)malloc(sizeof(HeapNode) * (cap + 5));
    h->sz = 0;
    h->cap = cap + 5;
}

static void heap_push(Heap *h, ll dist, int v, int used) {
    if (h->sz + 1 >= h->cap) {
        h->cap <<= 1;
        h->a = (HeapNode *)realloc(h->a, sizeof(HeapNode) * h->cap);
    }
    int i = ++h->sz;
    h->a[i].dist = dist;
    h->a[i].v = v;
    h->a[i].used = used;
    while (i > 1) {
        int p = i >> 1;
        if (h->a[p].dist <= h->a[i].dist) break;
        HeapNode tmp = h->a[p];
        h->a[p] = h->a[i];
        h->a[i] = tmp;
        i = p;
    }
}

static int heap_empty(Heap *h) {
    return h->sz == 0;
}

static HeapNode heap_pop(Heap *h) {
    HeapNode ret = h->a[1];
    h->a[1] = h->a[h->sz--];
    int i = 1;
    while (1) {
        int l = i << 1, r = l + 1, s = i;
        if (l <= h->sz && h->a[l].dist < h->a[s].dist) s = l;
        if (r <= h->sz && h->a[r].dist < h->a[s].dist) s = r;
        if (s == i) break;
        HeapNode tmp = h->a[s];
        h->a[s] = h->a[i];
        h->a[i] = tmp;
        i = s;
    }
    return ret;
}

static void add_edge(int *head, Edge *edges, int *ecnt, int u, int v, int w) {
    edges[*ecnt].to = v;
    edges[*ecnt].w = w;
    edges[*ecnt].next = head[u];
    head[u] = (*ecnt)++;
}

int main(void) {
    int R, C;
    if (scanf("%d %d", &R, &C) != 2) return 0;

    int N = R * C;
    int maxEdges = 4 * N + 10;
    Edge *edges = (Edge *)malloc(sizeof(Edge) * maxEdges);
