    for (int i = 0; i < N; i++) head[i] = -1;
    int ecnt = 0;

    /*
      Input format assumed:
      - R lines of horizontal doors between row i and i+1, each with C integers
      - R-1 such lines? and R lines of vertical doors? 

      Since the original statement text is incomplete here, we use the standard
      rectangular-maze format:
      For each cell, doors to right and down are given.
      Specifically:
        for i = 0..R-1
          for j = 0..C-2 : right door cost between (i,j) and (i,j+1)
        for i = 0..R-2
          for j = 0..C-1 : down door cost between (i,j) and (i+1,j)

      0 means no door/passage impossible, positive means number of cards needed.
    */

    int **right = (int **)malloc(sizeof(int *) * R);
    int **down = (int **)malloc(sizeof(int *) * (R - 1 > 0 ? R - 1 : 1));

    for (int i = 0; i < R; i++) {
        right[i] = (int *)malloc(sizeof(int) * (C - 1 > 0 ? C - 1 : 1));
        for (int j = 0; j < C - 1; j++) scanf("%d", &right[i][j]);
    }
    for (int i = 0; i < R - 1; i++) {
        down[i] = (int *)malloc(sizeof(int) * C);
        for (int j = 0; j < C; j++) scanf("%d", &down[i][j]);
    }

    for (int i = 0; i < R; i++) {
        for (int j = 0; j < C; j++) {
            int u = i * C + j;
            if (j + 1 < C && right[i][j] > 0) {
                int v = i * C + (j + 1);
                add_edge(head, edges, &ecnt, u, v, right[i][j]);
                add_edge(head, edges, &ecnt, v, u, right[i][j]);
            }
            if (i + 1 < R && down[i][j] > 0) {
                int v = (i + 1) * C + j;
                add_edge(head, edges, &ecnt, u, v, down[i][j]);
                add_edge(head, edges, &ecnt, v, u, down[i][j]);
            }
        }
    }

    int S = 0, T = N - 1;

    /*
      We need the minimum number of cards guaranteeing passage even if at most
      one door on the chosen route is broken.

      Model:
      - State (v,0): no broken door encountered/used yet
      - State (v,1): already handled one broken door
      Traversing an edge of cost w:
      - If door works: (u,k) -> (v,k) cost +w
      - If this door is broken and we haven't used the broken-door allowance:
            we try it, card returns, cannot pass through it, so this edge cannot
            be used to move. Therefore to guarantee success against any single
            broken door on the attempted route, the path must remain feasible
            after deleting any one edge on it.

      This is exactly the minimum total weight of two edge-disjoint s-t paths,
      where cards needed are the sum of both path costs, and we can follow one;
      if one door on it is broken, we can still use the other route.

      By Menger + min-cost 2-flow on unit capacities.
    */

    int M = ecnt / 2;
    int V = N;
    int SS = V, TT = V + 1;
    int FV = V + 2;

    int flowNodes = FV;
    int flowMaxEdges = 2 * (2 * M + 2 * V + 10);

    typedef struct {
        int to, next, cap, cost;
    } FEdge;

    FEdge *fe = (FEdge *)malloc(sizeof(FEdge) * flowMaxEdges);
    int *fh = (int *)malloc(sizeof(int) * flowNodes);
    for (int i = 0; i < flowNodes; i++) fh[i] = -1;
    int fcnt = 0;

    #define FADD(u,v,cap,cost) do { \
        fe[fcnt].to=(v); fe[fcnt].cap=(cap); fe[fcnt].cost=(cost); fe[fcnt].next=fh[(u)]; fh[(u)]=fcnt++; \
        fe[fcnt].to=(u); fe[fcnt].cap=0; fe[fcnt].cost=-(cost); fe[fcnt].next=fh[(v)]; fh[(v)]=fcnt++; \
    } while(0)

    FADD(SS, S, 2, 0);
    FADD(T, TT, 2, 0);

    for (int u = 0; u < N; u++) {
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            int w = edges[e].w;
            if (u < v) {
                FADD(u, v, 1, w);
                FADD(v, u, 1, w);
            }
        }
    }

    int need = 2, flow = 0;
    ll cost = 0;
    ll *dist = (ll *)malloc(sizeof(ll) * flowNodes);
    int *pv = (int *)malloc(sizeof(int) * flowNodes);
    int *pe = (int *)malloc(sizeof(int) * flowNodes);
    int *inq = (int *)malloc(sizeof(int) * flowNodes);

    while (flow < need) {
        for (int i = 0; i < flowNodes; i++) {
            dist[i] = INF;
            pv[i] = -1;
            pe[i] = -1;
            inq[i] = 0;
        }

        Heap hp;
        heap_init(&hp, flowNodes * 4 + 10);
        dist[SS] = 0;
        heap_push(&hp, 0, SS, 0);

        while (!heap_empty(&hp)) {
            HeapNode hn = heap_pop(&hp);
            int u = hn.v;
            if (hn.dist != dist[u]) continue;
            for (int e = fh[u]; e != -1; e = fe[e].next) {
                if (fe[e].cap <= 0) continue;
                int v = fe[e].to;
                ll nd = dist[u] + fe[e].cost;
                if (nd < dist[v]) {
                    dist[v] = nd;
                    pv[v] = u;
                    pe[v] = e;
                    heap_push(&hp, nd, v, 0);
                }
            }
        }

        free(hp.a);

        if (dist[TT] >= INF / 2) break;

        int addf = need - flow;
        for (int v = TT; v != SS; v = pv[v]) {
            if (pv[v] == -1) { addf = 0; break; }
            if (fe[pe[v]].cap < addf) addf = fe[pe[v]].cap;
        }
        if (addf == 0) break;

        for (int v = TT; v != SS; v = pv[v]) {
            fe[pe[v]].cap -= addf;
            fe[pe[v] ^ 1].cap += addf;
        }
        flow += addf;
        cost += dist[TT] * addf;
    }

    if (flow < 2) printf("-1\n");
    else printf("%lld\n", cost);

    return 0;
}

