/*
We model the maze as an (R x C) grid of rooms.
Moving between adjacent rooms may require:
- 0 cards: no door
- 1 card: there is a door
Walls without passage are absent from adjacency.

Exactly one door may be broken, and we don't know which one.
If we try to pass a broken door, the card is returned and we stay in place.
So to guarantee reaching the target, we need enough cards for the worst case:
for every possible broken door, the minimum number of successful door traversals
needed from start to finish in the graph with that door removed.

Answer = maximum over all doors d ( shortest path door-count from S to T with d removed )
If no path exists for some broken door, answer = -1.

Also include the case of "no broken door", but it is never larger than removing some door,
so not necessary separately.

Input format assumed:
R C
R lines describing horizontal separators between row i and i+1, each line has C chars
R-1 lines? No official statement included here, so we use the common format:
There are 2*R-1 lines after R C:
- even indexed room-row lines contain C-1 chars for vertical connections
- odd indexed separator lines contain C chars for horizontal connections

Characters:
'0' : open passage, cost 0
'1' : door, cost 1
any other char : wall / no passage

Start = top-left room (0,0), target = bottom-right room (R-1,C-1)

Because the original statement snippet omits the exact encoding, this solution is written
for the standard 0/1/wall maze encoding used in such tasks.

Algorithm:
- Build undirected graph of rooms; each edge has weight 0/1 and doorId if weight=1.
- For each door edge:
    run 0-1 BFS from source to target while skipping that doorId.
    if unreachable => -1
    track maximum distance.
- If there are no doors, just run once with no removal => 0 if reachable else -1.

This is efficient enough for moderate grids.
*/

public class Main {
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        String nextNonEmptyLine() throws IOException {
            String s;
            while ((s = br.readLine()) != null) {
                if (!s.isEmpty()) return s;
            }
            return null;
        }
    }

    static class Edge {
        int to, w, doorId;
        Edge(int to, int w, int doorId) {
            this.to = to;
            this.w = w;
            this.doorId = doorId;
        }
    }

    static int R, C, N;
    static ArrayList<Edge>[] g;
    static int doorCount = 0;

    static int id(int r, int c) {
        return r * C + c;
    }

    static void addEdge(int a, int b, int w) {
        int doorId = (w == 1 ? doorCount++ : -1);
        g[a].add(new Edge(b, w, doorId));
        g[b].add(new Edge(a, w, doorId));
    }

    static int zeroOneBfs(int bannedDoor) {
        int[] dist = new int[N];
        Arrays.fill(dist, Integer.MAX_VALUE);
        Deque<Integer> dq = new ArrayDeque<>();
        dist[0] = 0;
        dq.addFirst(0);

        while (!dq.isEmpty()) {
            int u = dq.pollFirst();
            int du = dist[u];
            if (u == N - 1) return du;
            for (Edge e : g[u]) {
                if (e.doorId == bannedDoor) continue;
                int nd = du + e.w;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    if (e.w == 0) dq.addFirst(e.to);
                    else dq.addLast(e.to);
                }
            }
        }
        return Integer.MAX_VALUE;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first = fs.next();
        if (first == null) return;
        R = Integer.parseInt(first);
        C = fs.nextInt();
        N = R * C;

        g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();

        // Read the remaining 2*R-1 structural lines.
        // We accept lines possibly containing spaces; remove spaces.
        BufferedReader br = fs.br;
        List<String> lines = new ArrayList<>();
        while (lines.size() < 2 * R - 1) {
            String line = br.readLine();
            if (line == null) break;
            line = line.replace(" ", "");
            if (line.length() == 0) continue;
            lines.add(line);
        }

        if (lines.size() != 2 * R - 1) {
            // If input format differs, fail gracefully.
            System.out.println(-1);
            return;
        }

        for (int r = 0; r < R; r++) {
            String vertical = lines.get(2 * r);
            // vertical connections inside row r: length C-1
            for (int c = 0; c < C - 1 && c < vertical.length(); c++) {
                char ch = vertical.charAt(c);
                if (ch == '0' || ch == '1') {
                    addEdge(id(r, c), id(r, c + 1), ch - '0');
                }
            }

            if (r < R - 1) {
                String horizontal = lines.get(2 * r + 1);
                // horizontal connections between row r and r+1: length C
                for (int c = 0; c < C && c < horizontal.length(); c++) {
                    char ch = horizontal.charAt(c);
                    if (ch == '0' || ch == '1') {
                        addEdge(id(r, c), id(r + 1, c), ch - '0');
                    }
                }
            }
        }

        if (doorCount == 0) {
            int d = zeroOneBfs(-2);
            System.out.println(d == Integer.MAX_VALUE ? -1 : d);
            return;
        }

        int ans = 0;
        for (int banned = 0; banned < doorCount; banned++) {
            int d = zeroOneBfs(banned);
            if (d == Integer.MAX_VALUE) {
                System.out.println(-1);
                return;
            }
            ans = Math.max(ans, d);
        }

        System.out.println(ans);
    }
}

