            int u = id(r,c);
            if (grid[r][c] == 'd') {
                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d], nc = c + dc[d];
                    if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
                    if (grid[nr][nc] == '#') continue;
                    int v = id(nr,nc);
                    // using door as u->v
                    if (distS[u] < INF && distE[v] < INF)
                        costs.push_back(distS[u] + 1 + distE[v]);
                    // using door as v->u
                    if (distS[v] < INF && distE[u] < INF)
                        costs.push_back(distS[v] + 1 + distE[u]);
                }
            }
        }
    }
    // also the path with no door usage
    costs.push_back(distS[end]);

    sort(costs.begin(), costs.end());
    costs.erase(unique(costs.begin(), costs.end()), costs.end());

    if (costs.size() == 1) {
        // Only one distinct cost means breaking any door on that path may block it entirely
        // Check if there's an alternative path with same or higher cost
        // Actually if only one path exists, answer is -1 because breaking a door on it blocks
        // But we need to check if there's any door on that path
        // We'll compute if any door is on the unique shortest path:
        // Simple: if distS[end] is the only cost and there's at least one door on that path,
        // then answer is -1; else answer = distS[end] (no doors).
        // Since the problem says "one door may be broken", if no doors exist, answer = distS[end].
        bool hasDoor = false;
        for (int r = 0; r < R; r++)
            for (int c = 0; c < C; c++)
                if (grid[r][c] == 'd') hasDoor = true;
        if (hasDoor) cout << -1 << "\n";
        else cout << distS[end] << "\n";
        return 0;
    }

    // The answer is the second smallest distinct cost
    cout << costs[1] << "\n";
    return 0;
}

