#include <bits/stdc++.h>
using namespace std;

/*
We model the maze as an R x C grid of rooms.
Moving between adjacent rooms may require:
- no card (open passage),
- one card (a door),
- impossible (wall).

Exactly one door in the whole maze may be broken, or none may be broken.
A broken door behaves like a wall, but you do not know which door it is.
We need the minimum number of cards that guarantees reaching from start to finish
for every possibility of at most one broken door.

Interpretation:
If we choose a route adaptively, then when we try a broken door, the card is returned
and we learn that particular door is unusable. To guarantee success against any single
broken door, the set of doors we decide to rely on must remain navigable after removing
any one door. In graph terms, we need an s-t subgraph with no bridge on all possible
s-t traversals, i.e. two edge-disjoint s-t paths in terms of door-edges uncertainty.
Since free passages cost 0 and doors cost 1, the minimum guaranteed number of cards is
the minimum total number of door traversals needed to obtain two edge-disjoint s-t paths.
If there are no doors on a path, cost is 0. If impossible, answer -1.

This is a min-cost flow of 2 units with unit capacity on each traversable adjacency edge:
- each undirected adjacency becomes two directed arcs with capacity 1 and cost w (0 or 1)
  through an edge-node trick to enforce undirected edge capacity 1 total.
Simpler: split each undirected edge into a gadget:
   u -> e (cap1,cost0), v -> e (cap1,cost0), e -> u (cap1,costw), e -> v (cap1,costw)
But that doesn't enforce total use <=1 correctly for both directions combined.

Better:
For each undirected edge (u,v,w), create two directed edges u->v and v->u each cap1 costw.
This allows both paths to use the same undirected edge in opposite directions, which cannot
happen in simple s-t flow of positive/zero cost without creating wasteful cycles in an optimal
2-unit s-t flow. So standard directed duplication is sufficient here.

Then:
- If min-cost flow of 2 from s to t exists, answer its cost.
- Else -1.

Input format assumption (standard for this maze problem family):
First line: R C
Then R lines describing horizontal walls/doors between cells? Unfortunately statement excerpt
omits exact format.

Because the exact original format is missing, we implement the common format:
For each of R rows:
  line with C-1 integers for doors/passages between horizontally adjacent cells
For each of R-1 rows:
  line with C integers for doors/passages between vertically adjacent cells

Value meaning:
0 = open passage
1 = door
-1 = wall
This is the most natural compact representation.

If your judge uses a different format, the logic remains the same but parsing must be adapted.
*/

struct Edge {
    int to, rev, cap, cost;
};

struct MinCostFlow {
    int n;
    vector<vector<Edge>> g;
    MinCostFlow(int n): n(n), g(n) {}

    void addEdge(int s, int t, int cap, int cost) {
        Edge a{t, (int)g[t].size(), cap, cost};
        Edge b{s, (int)g[s].size(), 0, -cost};
        g[s].push_back(a);
        g[t].push_back(b);
    }

    pair<int,int> minCostFlow(int s, int t, int maxf) {
        const int INF = 1e9;
        int flow = 0, cost = 0;
        vector<int> dist(n), pv(n), pe(n), inq(n);

        while (flow < maxf) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;
            deque<int> q;
            q.push_back(s);
            inq[s] = 1;

            while (!q.empty()) {
                int v = q.front(); q.pop_front();
                inq[v] = 0;
                for (int i = 0; i < (int)g[v].size(); ++i) {
                    Edge &e = g[v][i];
                    if (e.cap <= 0) continue;
                    if (dist[e.to] > dist[v] + e.cost) {
                        dist[e.to] = dist[v] + e.cost;
                        pv[e.to] = v;
                        pe[e.to] = i;
                        if (!inq[e.to]) {
                            inq[e.to] = 1;
                            if (!q.empty() && dist[e.to] < dist[q.front()]) q.push_front(e.to);
                            else q.push_back(e.to);
                        }
                    }
                }
            }

            if (dist[t] == INF) break;

            int addf = maxf - flow;
            for (int v = t; v != s; v = pv[v]) {
                addf = min(addf, g[pv[v]][pe[v]].cap);
            }
            for (int v = t; v != s; v = pv[v]) {
                Edge &e = g[pv[v]][pe[v]];
                e.cap -= addf;
                g[v][e.rev].cap += addf;
            }
            flow += addf;
            cost += addf * dist[t];
        }
        return {flow, cost};
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int R, C;
    if (!(cin >> R >> C)) return 0;

    auto id = [&](int r, int c) { return r * C + c; };
    int N = R * C;
    MinCostFlow mcf(N);

    // Horizontal adjacencies: R rows, each with C-1 values
    for (int r = 0; r < R; ++r) {
        for (int c = 0; c < C - 1; ++c) {
            int x; cin >> x;
            if (x == -1) continue;
            int w = (x == 1 ? 1 : 0);
            int u = id(r, c), v = id(r, c + 1);
            mcf.addEdge(u, v, 1, w);
            mcf.addEdge(v, u, 1, w);
        }
    }

    // Vertical adjacencies: R-1 rows, each with C values
    for (int r = 0; r < R - 1; ++r) {
        for (int c = 0; c < C; ++c) {
            int x; cin >> x;
            if (x == -1) continue;
            int w = (x == 1 ? 1 : 0);
            int u = id(r, c), v = id(r + 1, c);
            mcf.addEdge(u, v, 1, w);
            mcf.addEdge(v, u, 1, w);
        }
    }

    int s = 0, t = N - 1;
    auto [flow, cost] = mcf.minCostFlow(s, t, 2);

    if (flow < 2) cout << -1 << '\n';
    else cout << cost << '\n';

    return 0;
}

import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    idx = 0
    H = int(input_data[idx]); idx += 1
    W = int(input_data[idx]); idx += 1

    grid = []
    for _ in range(H):
        grid.append(input_data[idx:idx+W])
        idx += W

    # Locate start and goal
    start = goal = None
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)

    # Collect door positions and assign IDs
    door_id = {}
    door_positions = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'D':
                door_id[(i, j)] = len(door_positions)
                door_positions.append((i, j))

    D = len(door_positions)
    # BFS over (x, y, mask) where mask bits = doors already known broken
    # dist[x][y][mask] = minimum cards used in the worst case
    INF = 10**9
    dist = [[[INF] * (1 << D) for _ in range(W)] for _ in range(H)]

    dq = deque()
    dist[start[0]][start[1]][0] = 0
    dq.append((start[0], start[1], 0))

    dirs = [(1,0), (-1,0), (0,1), (0,-1)]

    while dq:
        x, y, mask = dq.popleft()
        d = dist[x][y][mask]
        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if not (0 <= nx < H and 0 <= ny < W):
                continue
            cell = grid[nx][ny]
            if cell == '#':
                continue
            if cell == 'D':
                did = door_id[(nx, ny)]
                if (mask >> did) & 1:
                    # already known broken, can pass freely
                    if dist[nx][ny][mask] > d:
                        dist[nx][ny][mask] = d
                        dq.appendleft((nx, ny, mask))
                else:
                    # we must try the door
                    # Case 1: door works, we pass but need +1 card (worst-case)
                    if dist[nx][ny][mask] > d + 1:
                        dist[nx][ny][mask] = d + 1
                        dq.append((nx, ny, mask))
                    # Case 2: door broken, we mark it as broken and stay in same room
                    new_mask = mask | (1 << did)
                    if dist[x][y][new_mask] > d + 1:
                        dist[x][y][new_mask] = d + 1
                        dq.append((x, y, new_mask))
            else:
                # empty or start or goal
                if dist[nx][ny][mask] > d:
                    dist[nx][ny][mask] = d
                    dq.appendleft((nx, ny, mask))

    gx, gy = goal
    ans = min(dist[gx][gy])
    print(-1 if ans == INF else ans)

if __name__ == "__main__":
    solve()
